) AS (
  VALUES 
    (537::BIGINT, 'No es muy buena dando retroalimentación; en ocasiones puede pasar por grosera, podría practicar más la comunicación asertiva. Para primeros ingresos no la recomiendo, especialmente si no llevó lab en el cole.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-05-08T00:00:00+00:00'::TIMESTAMPTZ, '510fc5457e5d59e223888ac2b866947ca85709d83e3434145a2a7dffbcb4eec3'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Es estricta pero buena, le importa más el pensamiento científico que el conocimiento en química por lo que vale mucho la pena para un aprendizaje integral. Eso si no da las calificaciones si no hasta el último día.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'a4025027d6c39b041a978b729728423556ad92243c32b75600bb97fecaeb02c4'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'aa4182685ff3efacbccedb0edbdca6ec4935d60fea61b0ec43c17031f1e97c94'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'No se como era antes pero ahorita 2025 muy buena profe, super amable, eso si como Tip recomiendo no hacerle preguntas de cosas que se supone que usted ya debería de saber porque si responde medio groserillo, pero el resto muy bien, no entiendo la calificación tan baja'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '0b5e6e7490fe817fd910246f537a1d8b5696d1156c1deba76663bf65db2a7dea'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Es una gran persona, solo que si espera que sepas que vas a llegar a hacer a la clase, sino no se detiene a explicar mucho. Los quizes son virtuales y muy fáciles y pide la libreta completa. Exigente pero si ve que eres aplicado y te interesas en la clase todo fluye bien. Profe favorita'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '7f3ba9ba8cd9e866cc3c2df3bf763ea59ebda636c676638c99e89d2a099eaf49'::TEXT, ARRAY[567, 613, 3169]::BIGINT[]),
    (537::BIGINT, 'reina la amo no entiendo como tiene una nota tan baja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'dedfe67b99e5b62ae9e16552f9c29984ba462a7086b8c5dd4070a933650ed1d9'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Muy buena profe, quices virtuales demasiado fácil y casi no suele revisar la libreta. Los informes se califican moderadamente. Si usted es muy muy sensible no la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-06T00:00:00+00:00'::TIMESTAMPTZ, '4d301583ac975f86459fe60a18315e162d79340842aca7c37004d714e0199b44'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Simplemente no es opción, ella espera que usted sepa absolutamente todo y hace preguntas en clase y si usted no sabe, le pregunta que para qué está ahí sino sabe nada, califica horrible y se pasa de mala nota, el asistente es otro que tampoco se compadece de nadie, que sea su última opción.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1c8c83b66df600b739f3b68aa9565f2f1b53f75d0f1fd6aa7de8e26af4047a34'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'No la recomiendo para primeros ingresos, es poco paciente y espera que ya sepan cosas que evidentemente aún desconocen (califica de la misma manera). A veces puede llegar de malas y lo hará notar, además no da retroalimentación, simplemente espera que vuelvan a hacer lo mismo, pero esa vez bien.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e3b664fe2ecc8d747dc12c49d3cf2703ffe84e7f5357697a8fa562ba351ee37b'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Una buena profesora, cuando explica supone que ya estudiaste de antemano y explica por encima, es bastante estricta en entregas de informes, es una buena opción si vas preparado. No recomendable para todos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '101c70c95f37b46868ddda7e763d8c89eb8125c7c397132546ed02bb42e528a9'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'NO MATRICULE CON ELLA! Ella hará que usted se sienta mal y cree que todos vamos a ser químicos, ella no regala un punto y si le falta algo para pasar, ella nunca le dará absolutamente nada, ella en el primer examen pregunta a los estudiantes uno por uno porqué les fue mal solo por metiche.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0e7b8778c0b409e828c4e30d829859be1ba18ad4c9a2f561dddaa535dbf08da9'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Una profe sumamente cariñosa que busca apoyar a sus estudiantes lo más que pueda. Sus explicaciones son buenas, y sabe muchísimo. Ha evolucionado mucho como profesora y su clase es muy entretenida. Eso si, no le falte con informes ni con la libreta porque es estricta.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '40ede790193c628ab1e5dcd8b8e4c46abd53543f32c87d9b3487754891d31eb9'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Aunque en el pasado estuvo calificada como de las peores profes del Tec yo no la calificaría tan bajo, Los quizes son en teams en un formulario y se enoja si no participan en clase, no es ni la peor ni la mejor profe pero aconsejo que si puede matricular con otra persona lo haga.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4f51d1b7c526b3d80853806cef21ea5ab58a5013ce9dde3310b5241d5ed34a8a'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Es una buena profe, hace siempre una charla al principio de la clase, reflexiona con uno. Los estudiantes la quieren mucho. Los quices son en el aula pero por medio de forms y su forma de explicar es buena.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'dbdf55fe7ef227af323a4f169111d5ee1582d59013ec73dbd734cf8ee53b1e28'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Excelente profesora, se esfuerza por dar buenas clases y se esfuerza por ser amable y clara con sus instrucciones. No le gusta regañar, es muy paciente. Sin embargo, no le faltes con tareas ni trabajos por que es estricta con eso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-05-28T00:00:00+00:00'::TIMESTAMPTZ, '6e9bc9a250a67b38647d2278c474e4f2da48a75490ae55a9b6c06bea3eb5f289'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Es una mujer y una profe increíble, sabe un montón y tiene bastante experiencia en lo que hace. Le gusta y espera que unx estudie antes de las prácticas para solo aclarar dudas, si hay que ponerle con los reportes y quices. Llevé este curso virtual, de fijo presencial la hubiera aprovechado más.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-14T00:00:00+00:00'::TIMESTAMPTZ, '46bdeff767ec9dd79736a91983db819e838cdd2f6635a3196de86544fab8b287'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'La profe es excelente, siempre antes de la clase realizaba una reflexión de temas súper importantes y después ya explicaba el tema y los informes. Hay que estudiar y tener claro el tema para los exámenes cortos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'b9764101b27674cc39c4d767e27ccfab1fd917a995a95915b9e6c4ffb410a1de'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (537::BIGINT, 'Jaja el mae anterior de fijo no pasó'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f0e814417823fb86d162d42f32439a820782c109201d9da818c1f9938afea017'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (537::BIGINT, 'Espera que uno llegue a clase con la materia aprendida y le molesta cuando los estudiantes no participan. Si hace todos los cuestionarios, quices y se muerde para los informes, le va a ir bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b3d122b3cdc0a178b21559854b8ab3ead7b62c39f360803f085fdac30b7f5b0a'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'la amo mae es la mejor pasa uno sobrado el curso si se muerde'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd27507ae496ce1ab05c87f3f03a683d4d4e24908a723dd04e5eead02655eb6eb'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Una profe muy buena, si usted participa en clase y se muerde la lleva bien, es muy open mind y ayuda a quien ve que se esfuerza'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '8743b296ff4c53667acb0e6114a730fa4dc12d6c090696722cf21d9929d03565'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'c9752871fa4a8cd297b481e1843c06a2de6d5d344dd2c98d601929fab5285da3'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2022-03-22T00:00:00+00:00'::TIMESTAMPTZ, 'efc28b0f4da1e05b41beeb163d642d100bbb86bcdb38bf61d959cf63383ad379'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-09T00:00:00+00:00'::TIMESTAMPTZ, '8a81f0cea2b521ee485faec32dae264a4ef1b545fb0cf681374d020a711699e7'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'Es un curso bastante pesado, recomiendo ponerle al inicio porque las evaluaciones no son dificiles y el porcentaje cuenta. Ella se preocupa por que unx aprenda y en cada entrega deja anotaciones/recomendaciones. Siempre pasa lista.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-12T00:00:00+00:00'::TIMESTAMPTZ, '71b54e025b62556f2951ead0a2c884f6250fed737215a035abf62c6077d5ea46'::TEXT, ARRAY[3169]::BIGINT[]),
    (537::BIGINT, 'La Profe es super buena persona .super comprensiva .,se preocupa un montón porque uno aprenda y además explica de manera exelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-30T00:00:00+00:00'::TIMESTAMPTZ, '722d546daf3ca8d6a119049325a80e0e06a1320366f69bea66376a775660292d'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Tengo un crush con ella. Es la mejor profe con la que he recibido clases en toda mi vida. 100% recomendada. Si quieren pasar esta materia matricular con ella es la mejor opción posible. Es la mejor persona que he conocido... y Amilkar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '5247cd208a19fde91ea8534f5abede09987608d56f97ec57192e5bffb39c4374'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'sinceramante la experiencia durante el semestre con ella no es tan mal, recomiendo leer y estudiar bien el manual antes de cada clase, poner bastante atención, y ser muy extenso a la hora de responder'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '77b488a5ed38cca8326939e1719eeefa1165e04c46835ad3dd897854e470be1d'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'La profe al principio es un toque seria, pero ya después se vuelve super buena nota, de parte de ella es buena nota la verdad. Los que califican duro son los asistentes que tiene, pero nada más muérdase en los quiz y cuestionarios previos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'ae79bf5a8103d3bba1c39bcb33be3097fec6e3adc3208f9bf713142dad87dce7'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'La profesora es excelente el primer día impresiona mucho porque se ve de carácter fuerte, pero con el pasar de las clases te das cuenta que es un amor, además de que explica super bien y es muy accesible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6b9031516cec82f3b6b4403b94709fdd8fb56072dc497a5905ba47a742e19196'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'La profe es algo estricta pero eso a uno le ayuda bastante a mejorar como estudiante. Explica muy claro, las clases son interesantes e incluso cómicas. No es tan dura revisando informes. Vaya preparado y léase el manual muy bien antes de cada clase. Tomaría su clase otra vez.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '60cd2cf2bc975149eda3898ab33f719534f856fc51225d5d61bd5145728acc70'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, '(VIRTUAL!!) Las clases son demasiado largas y pueden ser bastante aburridas luego de un tiempo. La profe sin duda sabe mucho pero se confunde demasiado al explicar. Para los quizes hay que estudiar y es difícil sacarse un 100 en un informe(:'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'ed4ede2c4cbe3657315c8425c391a7e38a0ab5a361765dc787aae256ac3fb1db'::TEXT, ARRAY[3169]::BIGINT[]),
    (537::BIGINT, 'La profe no es tan mala como dicen. Es estricta pero puede llegar a ser cómica. Es muy ordenada y explica muy claramente las prácticas. No es mala opción'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'ea2c12370e2c0221861405b1413a16750edc0b215f376fd53c31e796bee86f79'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'De forma virtual es súper ordenada, es buena nota aunque un poco estricta. Explica bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '942a4e47f4083d9e2e6228acd3fc93d2edc7c0d937d7d9384b504016c5ccae7f'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Se adaptó muy bien a la plataforma Teams, es buena profe sólo que tal vez hay aspectos muy pequeños de los informes que no explica bien. Se pasa fácil si se estudia antes de cada quiz y para el informe'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '5e153d4cfd903790bd8f278f49888b9ec3100fe02d370aa47504afa720ba32fd'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Excelente profe, se preucupa por todos, hace quices previos muy faciles y si se lleva la libreta al dia se pasa super facil, hace las clases divertidas, recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'ac85d533de643c43ff3d56d0b297369e5d1d0f699d568bc2a7a1499195d1fcb4'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Es una profesora excelente, es exigente pero eso le ayuda a uno a hacer las cosas de la mejor manera posible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '092cdf0d25a05d1be5fa52919bfaa797055c0b996dfe242de85ea71910d519c7'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'Si usted lleva la libreta al día no tiene por qué irle mal, leerse MUY bien el manual antes de las clases y si hace bien los informes va a volar en el examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-03-03T00:00:00+00:00'::TIMESTAMPTZ, '8eb9593a1efc2470231e12af2f2a3c72cbbfa65e816e20c228976eebfa209bae'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Evitenla, lo peorsito de la escuela.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'f7a604cbfbe073c030bbd2b48318ec4ce51cad14255b76400fab80dff703e9b5'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Súper graciosas son las clases. Leanse bien el manual porque hace preguntas antes de cada clase, sino hay respuestas se pone medio arenosa'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c3afebfbd5582ada90541c8a09dffef52a9ecdf5ca9f66bf065f8e34f04785c3'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Muy buena para la calificación que tiene,se interesa por el aprendizaje de todos. Pero tiene que mostrar su interés y ser responsable.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-27T00:00:00+00:00'::TIMESTAMPTZ, '2f7d7f8fef7c3e06633ca22d5dbffe7046f5ac6e96a277990d7352ded1835a34'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7019f89108b8fc7b58dfcd884d412eb06ebb4ec87daad45b85047ef7cdba8be3'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Demasiado fácil con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '28384c782ff78b3ff914aefa1e6a2f1caa0d9f7b30945c36e12704abb50a28c2'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Los quices son de la libreta, muchas veces con la libreta abierta y en grupo. Se pasa si se estudia. Es tranqui.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7beb3037ed5655b0abab71748c88d830e8c12ed3c51168434bf69adefe8ca462'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'No revisa la libreta, difícilmente aclara dudas y prácticamente hay que aprender todo solo. No la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '354c2db4ae750dc0babc0498f9fd9dc5a3cf353578e6a7bb26609fa55043b2dd'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'No revisa la libreta y los quices son fáciles'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0f0c078037bb0c153c4393c83fad96186c1cf101c24a4473a8edb2d57bb143ad'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'No explica bien, ni ayuda con la matería. Usted tiene que estudiar por cuenta propia, si se le complica la matería: cuidado. No se confíe.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c6cc72c7cd407d7aec269b141db3e39335804aeda92dd4d29b051a1ebcc2ebb3'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (537::BIGINT, 'No revisa libreta, es un poco vaga, si quiere pasar tiene que estudiar por su propia cuenta'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd508b97befe8e277c774c1b157be8b2c161e4e0c9ba4c85694fc37fae59438ab'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Hay que saber a lo que se va, conociendo todo casi sin necesidad de usar la libreta. A veces no le gusta que le pregunten porque ella ya lo explicó, pero no es imposible'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '028775807cfd9c43e1ba92777ff230844e8db81d18b03f3982d2f7426c2ced81'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Muy práctica, a veces tosca para responder, pero esa misma manera de tratar hace que uno entienda mejor lo que contestó, queda mejor plasmado, y uno le pone atención para no tener que preguntar otra vez.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '90db105c6b6770ef6865fa19f3b597d152d199823788ffbf331d4bc26718d8bf'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'af911883b990266c844802ce8254752e0dfde6046aed14a9b551fb7f9bba7e4d'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (537::BIGINT, 'ES DEMASIADO BUENA PARA LAB! ella es muy práctica e incluso "mañosa", le enseña a uno a entender las prácticas de la semana así que si hay que hacer la libreta a consciencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'aa8f5e0eb6847a9d15d00c3f646ffa2262a514c49265195894e59e9f24478bc0'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'La profe se esfuerza en que uno de verdad aprenda, y da ayuda en el examen. Hay quices todas las semanas sobre lo que diga la teoría de la práctica que corresponda y revisa la libreta como una vez en el curso. También es bastante simpática. Super recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'f64bd580cb6c99458117739a70a87ab50cb257c1e2aee5a71c7b8663f23d16d2'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'La profe revisa como 2 veces la libreta en todo el semestre. Le gusta que uno llegue al lab sabiendo lo que tiene que hacer y con que tiene que trabajar. Muy buena gente y vacilona.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'e8de945ea97c861b0083fc15b2ff77b2d04336e2600e98f478b9d0bec931f5ae'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Para lab es muy buena opción, es demasiado buena gente y le ayuda a uno un montón. Los quices son fáciles, generalmente de lo que se va a hacer en la práctica.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1ae6e9edfaa58177a289ea4bf54dbf9a62320f860d08551a818498ff3cfd8068'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Es buena profe, importante saber de que se trata la practica y hacer la libreta y es buena calificando.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'b788c68a6305718d91b768d781647e9d20405330341603921aee101462e6cae9'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7eb447df793f50e46aef9badf38651b5e278215836a4ddc4abc80012eac86b20'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Se enreda sola, uno le pregunta y no sabe qué responder incluso se lo manda de "tarea" a leer a internet o en algún libro. Además, manda a los estudiantes a dar la clase.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6ac626e81add8457f78e3bcae4d11adb581bd01fabcb8abe2570f55032f0c120'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Explica muy bien! Los quices son faciles e incluso grupales aveces. Se debe hacer la libreta (algunos quices es copiar alguna pregunta de ahi). Es muy pura vida. Se aprende mucho!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '6c15345862a5a4819bc69d8dba6068257d0d0af67e2c4e49ff31112b2c0b4ccf'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Muy suave a la hora de calificar exámenes, pero muy floja a la hora de explicar. Se enreda mucho y no es nada cuidadosa a la hora de manejar ella misma los instrumentos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '8a555460fb3a025e79c173c959f613398983c30d26d677b550d377f67168b14a'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Muy buena gente, califica un poco duro exámenes y reportes, pero tampoco tanto. No pide tareas y es muy fácil pasar si usted va a las clases, explica bien pero a veces se enreda.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '18b943104e9eb3a5f5f52052ab5c83799364c2c179e38bac6f64dab2b64a7ce5'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Sinceramente es una profesora excelente muy buena gente y ayuda mucho a los estudiantes si no saben como hacer los reportes o utilizar un instrmento'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '2316fd4422761fdc4b63124f667823af083a93952b724baf2a66f573e9d14379'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'df2f8301dbd679a33403c776a9e94fd37ea717dc072149cdd326dd483b7cb61e'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Da más tiempo en los laboratorio y se preocupa por sus estudiantes, no se preocupa por las tareas y además ayuda a utilizar los instrumentos como un profesional. Fue a Holanda y otros países a realizar estudios y sabe mucho.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-09T00:00:00+00:00'::TIMESTAMPTZ, '5f2e14d0e4617d4386863b19f028df83164ce410f9618231d511dc45cd7ab7e0'::TEXT, ARRAY[613, 3169]::BIGINT[]),
    (537::BIGINT, 'Unico curso en el que aprendi'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '95fed37acb925b2704cdeb3fd6bfb0d28611eedecbcde9a92bb0bb07279a622d'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Es buena gente... pero se enreda sola y a veces se confunda y cambia de tema... ademàs en ocasiones no sabe como responder una duda a los estudiantes... NO da materia y tras de eso escribe un desmadre en la pizarra que ni se entiende nada... hay que buscar como estudiar por aparte'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '6f5f8265a61168770c329a4c8bac627de8b3f620b7f2d00e1e404377ef6cc6a9'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Pésima, nada más que decir...'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '956405b5dc68592781187b6f8e9de0454d226b853c9e960518894a94685214b2'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Es pesima profesora, ella supone que uno tiene que saber la materia antes de entrar al aula porque ella no la explica, no da nada de materia todo se tiene que estudiar desde otros medios, es casi como hacer quimica por suficiencia'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '658a934398f6b3d27e1b938c2fe5dcf1e794e44d7bf9b8d2b1b3267da7ab09db'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'No sabe mucho. Tiene un tic verbal MUY distractor. Enseña con buenas intenciones pero sugiero matricular con otro.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0433f6ada8bc8149c7c7498823536f96ce3bd792fe6dd5840a4e3d4dab0cb8f8'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0eed8bbd734240c3a41f3661594212c3e6829a0f2760217d7de3549a6190acb7'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Pésima, no sabe ni lo que dice. No recomendada. No tiene la capacidad para contestar las preguntas de los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8bdb698027b537da0fe51e488053035a0d6c16e4eb9fdccca1f239ac69e6983d'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '14216d64db4fa45a5512103e300707f77629be47d7425d4223e4b876c0abd674'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'bf717aa9ec93849a248d0929cf4f25941c27d2f116bef4f78c945cccf093d411'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'no explica para nada bien'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'de79ed2a74492626337fca8296d0f3917f03a3939f6699f5df3e9c5fdc23e03c'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'aeec943a280ba936445ec5bc9626d581f3876f271ab1dc506bd50cad8c746160'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '9c7d8d046b8a6fb7967751cffff33e9dbd7756d81118cd77e3865ae417b741d4'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Muy graciosa y hace el laboratorio entretenido. Se disfruta y se aprende. Si va mal se lo dice en frente de todos para que se ponga a estudiar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '3ada09848f013906505c8107b03808b7537a7d7dfa7d4f9991807778ea9b8a62'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Pésima profesora, es muy simpática pero no sabe compartir su conocimiento, es pésima explicando y no tiene paciencia.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-09T00:00:00+00:00'::TIMESTAMPTZ, '5a19273f745084e475c7a851ad7827418b3be8db118b28619459901c35afea14'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Es el tipo de profesores que trata que el estudiante estudie solo y solo despeje dudas, no puede ser así todo, necesitas una base y después practicar para tener dudas, no todos tenemos la capacidad de ser empíricos, no ayuda al estudiante y cuando vez un estudiante que aprueba el curso es repitient.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1e65b626ecea9aca7ee68efdbd2fad68aa1357c37fd3152699f55d69649c3adb'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'No se duerme uno en las clases! Y ayuda demasiado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd1451b471ca59e0fa6ec014c94507495d9a51a18d87ef45c62b30c1bcf8e34ab'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Distraida, se enreda sola, no explica para nada bien.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '4887430052b13ed9e52f79007303b5e4b58e4bf7e5e7d210ab00b5f4214fd02a'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd474f7d3f8dbed1148dca0aaf7e1dd95a3e106f2fd021b23212483fbaad67b60'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '46f815e1172b6d8d5ba9c3420f5f8c59df6dd0555f055d40442c91366a154f26'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Ayuda montones si uno se espabila, explica cuantas veces sea necesario.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '5d9c9bc4211868d6ddf3f8e0b3f331dae3c316a28aa83be53c60c4160cb168e5'::TEXT, ARRAY[567]::BIGINT[]),
    (537::BIGINT, 'Mala profesora, por dicha fue un curso que se pasa solo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'baf8d9bea9fbac1c9735483909b7bf1377e939b6461bd6fad70ccd71e71270b7'::TEXT, ARRAY[567, 3169]::BIGINT[]),
    (537::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'f1aafeff6f70b691a02929716a60c661d533ed253245dd8c2b7d12993c64a0f9'::TEXT, ARRAY[567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
